from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]
            # check if key exists and not expired
            if key in cache:
                wtime = cache[key][1]
                if t - wtime >= ttl:
                    # expired, remove it
                    del cache[key]

            if key in cache:
                # update existing (still present, not expired)
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                # new entry
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)

        elif kind == 'get':
            if key in cache:
                value, wtime = cache[key]
                if t - wtime >= ttl:
                    # expired
                    del cache[key]
                    results.append(-1)
                else:
                    results.append(value)
                    cache.move_to_end(key)
            else:
                results.append(-1)

    return results

